if __name__ == '__main__':
    import csv
    from pathlib import Path
    ROOT = Path(__file__).resolve().parent.parent
    with open(ROOT / 'data/shiei_jutaku_boshu_R080701.csv', encoding='utf-8-sig') as f:
        rows = list(csv.DictReader(f))
    with open(ROOT / 'data/shiei_jutaku_kotsu_R080701.csv', 'w', encoding='utf-8-sig', newline='') as out:
        w = csv.writer(out)
        w.writerow(['区', 'PDFのNo.', '住宅（団地）', '最寄り駅', '最寄り駅_徒歩分', '記載の駅数', '最寄りバス停', '最寄りバス停_徒歩分', '交通機関（一覧の記載）'])
        for r in rows:
            e = T[r['区']][int(r['PDFのNo.']) - 1]
            rail = [x for x in e if not x[0].startswith('バス')]
            bus = [x for x in e if x[0].startswith('バス')]
            rr = min(rail, key=lambda x: x[1]) if rail else ('', '')
            bb = min(bus, key=lambda x: x[1]) if bus else ('', '')
            w.writerow([r['区'], r['PDFのNo.'], r['住宅（団地）'], rr[0], rr[1], len(rail), bb[0].replace('バス ', ''), bb[1],
                        '／'.join(f'{n} 徒歩約{m}分' for n, m in e)])
    print(f'data/shiei_jutaku_kotsu_R080701.csv: {len(rows)}行')
